update forms.form_definition d set current_version_id = v.id
  from forms.form_definition_version v where v.form_code = d.code and v.version_no = 1;


-- Every form has a current version and every approval form an approver.
do $$
begin
  if exists (select 1 from forms.form_definition where current_version_id is null) then raise exception 'form without a version'; end if;
  if exists (select 1 from forms.form_definition d where d.approval_required and not exists (select 1 from forms.form_entitlement e where e.form_code = d.code and e.action = 'APPROVE')) then raise exception 'approval form without approver'; end if;
  if exists (select 1 from forms.form_definition d where d.review_required and not exists (select 1 from forms.form_entitlement e where e.form_code = d.code and e.action = 'REVIEW')) then raise exception 'review form without reviewer'; end if;
end;
$$;
