insert into forms.form_definition
  (code, sequence_no, name_ar, name_en, purpose_ar, purpose_en, owner_role_hint, source_reference, review_required, approval_required, repeatable)
values
  ('WB-FRM-01', 1, 'نموذج تسجيل بلاغ / إحالة', 'Report / Referral Registration Form', 'تسجيل البلاغ أو الإحالة وإثبات مصدرها وبياناتها الأساسية.', 'Register the report or referral and record its source and basic data.', 'COMPLIANCE_INTAKE', 'GOVERNING_PROCEDURE + BUSINESS_REQUIREMENTS', false, false, true),
  ('WB-FRM-02', 2, 'تصنيف السرية وحماية المبلّغ', 'Confidentiality Classification and Reporter Protection', 'تحديد مستوى السرية وحماية هوية المبلّغ ومخاطر الإيذاء.', 'Set the confidentiality level, reporter identity protection and retaliation risk.', 'COMPLIANCE_INTAKE', 'WHISTLEBLOWING_POLICY', true, false, true),
  ('WB-FRM-03', 3, 'فحص اكتمال البيانات', 'Information Completeness Check', 'التحقق من الحد الأدنى للمعلومات اللازمة للتقييم.', 'Verify the minimum information needed for assessment.', 'COMPLIANCE_INTAKE', 'GOVERNING_PROCEDURE + BUSINESS_REQUIREMENTS', false, false, true),
  ('WB-FRM-04', 4, 'قرار إلغاء بلاغ لعدم الاستكمال', 'Report Cancellation Decision for Non-Completion', 'توثيق الإغلاق الإجرائي عند تعذر استكمال الحد الأدنى من البيانات.', 'Document the procedural closure when the minimum information cannot be completed.', 'COMPLIANCE_INTAKE', 'GOVERNING_PROCEDURE', true, true, true),
  ('WB-FRM-05', 5, 'تحديد الاختصاص', 'Jurisdiction Determination', 'تحديد طبيعة الموضوع والجهة المختصة ومسار المعالجة.', 'Determine the nature of the matter, the competent body and the handling path.', 'COMPLIANCE_INTAKE', 'GOVERNING_PROCEDURE', true, false, true),
  ('WB-FRM-06', 6, 'تحويل شكوى خدمية', 'Service Complaint Transfer', 'توثيق إعادة تصنيف وإحالة الموضوع بوصفه شكوى خدمية.', 'Document the reclassification and referral of the matter as a service complaint.', 'COMPLIANCE_INTAKE', 'GOVERNING_PROCEDURE', false, false, true),
  ('WB-FRM-07', 7, 'تقييم مبدئي', 'Initial Assessment', 'تقدير الجدية والمخاطر والأدلة الأولية وتحديد المسار التالي.', 'Assess seriousness, risk and initial evidence, and set the next path.', 'COMPLIANCE_INTAKE', 'GOVERNING_PROCEDURE', true, false, true),
  ('WB-FRM-08', 8, 'محضر إثبات تاريخ العلم بالمخالفة', 'Record of the Date of Knowledge of the Violation', 'توثيق التاريخ الذي تحقق فيه العلم الكافي بالمخالفة وسنده.', 'Document the date on which sufficient knowledge of the violation was established, and its basis.', 'COMPLIANCE_INTAKE', 'GOVERNING_PROCEDURE', true, false, true),
  ('WB-FRM-09', 9, 'قرار تصنيف نتيجة التقييم', 'Assessment Outcome Classification Decision', 'توثيق قرار الفرز النهائي والمسار الإجرائي التالي.', 'Document the final triage decision and the next procedural path.', 'COMPLIANCE_INTAKE', 'GOVERNING_PROCEDURE', true, true, true),
  ('WB-FRM-10', 10, 'تكليف تحقيق', 'Investigation Assignment', 'تحديد المحقق ونطاق التحقيق ومدته ومتطلبات الاستقلالية.', 'Define the investigator, the scope and duration of the investigation and the independence requirements.', 'COMMITTEE_SECRETARY', 'GOVERNING_PROCEDURE', true, true, true),
  ('WB-FRM-11', 11, 'سجل أدلة', 'Evidence Register', 'ملخص رقابي لسجل الأدلة الإلكتروني وسلامة سلسلة الحيازة.', 'Supervisory summary of the electronic evidence register and chain-of-custody integrity.', 'INVESTIGATOR', 'GOVERNING_PROCEDURE', true, false, true),
  ('WB-FRM-12', 12, 'تقرير تحقيق أولي', 'Preliminary Investigation Report', 'عرض نتائج التحقيق الأولي والأدلة والنتائج والتوصية.', 'Present the preliminary investigation results, evidence, findings and recommendation.', 'INVESTIGATOR', 'GOVERNING_PROCEDURE', true, false, true),
  ('WB-FRM-13', 13, 'قرار تشكيل لجنة تحقيق', 'Investigation Committee Formation Decision', 'توثيق قرار تشكيل اللجنة ونطاقها وأعضائها وإقرارات الاستقلال.', 'Document the committee formation decision, its scope, members and independence declarations.', 'COMMITTEE_SECRETARY', 'GOVERNING_PROCEDURE + COMMITTEE_CHARTER', true, true, true),
  ('WB-FRM-14', 14, 'محاضر جلسات لجنة التحقيق', 'Investigation Committee Meeting Minutes', 'توثيق الجلسات والمداولات والحضور والقرارات والتعارضات.', 'Document sessions, deliberations, attendance, decisions and conflicts.', 'COMMITTEE_SECRETARY', 'COMMITTEE_CHARTER + GOVERNING_PROCEDURE', true, true, true),
  ('WB-FRM-15', 15, 'إشعار بمخالفة وتمكين حق الدفاع', 'Notice of Violation and Right of Defence', 'إثبات إبلاغ الموظف وتمكينه من الرد وفق الضوابط.', 'Record that the employee was notified and enabled to respond under the applicable rules.', 'COMMITTEE_SECRETARY', 'GOVERNING_PROCEDURE', true, true, true),
  ('WB-FRM-16', 16, 'مسودة قرار تأديبي', 'Draft Disciplinary Decision', 'صياغة مسودة القرار/التوصية بعد استكمال التحقيق وحق الدفاع.', 'Draft the decision / recommendation after the investigation and right of defence are complete.', 'COMMITTEE_SECRETARY', 'GOVERNING_PROCEDURE', true, true, true),
  ('WB-FRM-17', 17, 'إشعار قرار', 'Decision Notice', 'توثيق تبليغ القرار النهائي المعتمد.', 'Document the notification of the approved final decision.', 'COMMITTEE_SECRETARY', 'GOVERNING_PROCEDURE', true, false, true),
  ('WB-FRM-18', 18, 'طلب تظلم', 'Grievance Request', 'تسجيل التظلم وفحصه والفصل فيه وفق المسار المعتمد.', 'Register, examine and decide the grievance through the approved path.', 'COMMITTEE_SECRETARY', 'GOVERNING_PROCEDURE', true, true, true),
  ('WB-FRM-19', 19, 'متابعة تنفيذ قرار', 'Decision Implementation Follow-up', 'متابعة تنفيذ القرار والإجراءات التصحيحية والتحقق من الإقفال.', 'Follow up the implementation of the decision and corrective actions and verify closure.', 'COMMITTEE_SECRETARY', 'GOVERNING_PROCEDURE', true, false, true);
